"""AST-based static analyzer for Python code generated by LLM agent.

Performs early heuristic linting to identify prohibited imports, builtins,
and file/system tampering patterns before execution.
"""

from __future__ import annotations

import ast
from dataclasses import dataclass

FORBIDDEN_MODULES: frozenset[str] = frozenset({
    "socket",
    "requests",
    "urllib",
    "urllib3",
    "http",
    "httpx",
    "aiohttp",
    "subprocess",
    "os",
    "shutil",
    "sys",
    "pathlib",
    "pty",
    "commands",
    "multiprocessing",
    "threading",
    "ctypes",
    "importlib",
    "posix",
    "posixpath",
    "nt",
    "ntpath",
    "webbrowser",
    "pickle",
    "shelve",
})

FORBIDDEN_CALLS: frozenset[str] = frozenset({
    "eval",
    "exec",
    "__import__",
    "compile",
    "globals",
    "locals",
})


@dataclass(frozen=True)
class ASTCheckResult:
    is_safe: bool
    reason: str | None = None
    violation_node: str | None = None


class _SafetyVisitor(ast.NodeVisitor):
    def __init__(self) -> None:
        self.violations: list[str] = []

    def visit_Import(self, node: ast.Import) -> None:
        for alias in node.names:
            base_module = alias.name.split(".")[0]
            if base_module in FORBIDDEN_MODULES:
                self.violations.append(f"Forbidden module import: '{base_module}'")
        self.generic_visit(node)

    def visit_ImportFrom(self, node: ast.ImportFrom) -> None:
        if node.module:
            base_module = node.module.split(".")[0]
            if base_module in FORBIDDEN_MODULES:
                self.violations.append(f"Forbidden module import from: '{base_module}'")
        self.generic_visit(node)

    def visit_Call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Name):
            if node.func.id in FORBIDDEN_CALLS:
                self.violations.append(f"Forbidden builtin call: '{node.func.id}'")
            elif node.func.id == "open":
                # Check write modes
                for arg in node.args[1:]:
                    if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
                        if any(mode in arg.value for mode in ("w", "a", "x", "+")):
                            self.violations.append("Forbidden file write operation via open()")
                for kw in node.keywords:
                    if kw.arg == "mode" and isinstance(kw.value, ast.Constant):
                        if any(mode in str(kw.value.value) for mode in ("w", "a", "x", "+")):
                            self.violations.append("Forbidden file write operation via open()")
        self.generic_visit(node)


def check_python_ast(code: str) -> ASTCheckResult:
    """Statically parse and validate code AST for prohibited elements."""
    try:
        tree = ast.parse(code)
    except SyntaxError as e:
        return ASTCheckResult(
            is_safe=False,
            reason=f"Python SyntaxError: {e}",
            violation_node="SyntaxError",
        )

    visitor = _SafetyVisitor()
    visitor.visit(tree)

    if visitor.violations:
        return ASTCheckResult(
            is_safe=False,
            reason="; ".join(visitor.violations),
            violation_node=visitor.violations[0],
        )

    return ASTCheckResult(is_safe=True)
